+    var issueNumbers = [];
+    var seenIssues = {};
+    asList(issueSearch).forEach(function (it) {
+        var n = parseInt(it && it.number, 10);
+        if (!isNaN(n) && n > 0 && !seenIssues[n]) {
+            seenIssues[n] = true;
+            issueNumbers.push(n);
+        }
+    });
