            { number: 1, labels: [], body: 'Closes #5', headRefName: '' }
        ]);
        assert.deepEqual(unlabeled.issueNumbers, []);
        assert.deepEqual(unlabeled.orphans, [], 'unlabeled PRs are ignored entirely');
    });

