        var fields = tc.fields || {};
        var historicalDoneBugs = fetchHistoricalDoneBugs(tc.key, tracker);
        totalHistoricalDoneBugs += historicalDoneBugs.length;
        return {
            key: tc.key,
            summary: fields.summary || '',
            description: fields.description || '',
