function scanTransformedFailedReason(fields, fieldName) {
    for (var key in fields) {
        if (fields.hasOwnProperty(key) && key.indexOf(fieldName) !== -1) {
            var v = fields[key];
            if (typeof v === 'string') return v;
            if (v && typeof v.value === 'string') return v.value;
