    }
    return '';
}

function extractAttachmentNames(fields) {
    var attachments = fields && fields.attachment;
    if (!Array.isArray(attachments)) return [];
    return attachments.map(function(a) { return a.filename || ''; }).filter(function(n) { return n; });
}

