 */
function extractLinkedIssueNumber(pr) {
    var m = bodyOf(pr).match(/\b(?:closes|fixes|resolves|part of)\s+#(\d+)/i);
    if (m) return parseInt(m[1], 10);
    m = branchOf(pr).match(/^(\d+)/);
    if (m) return parseInt(m[1], 10);
    m = branchOf(pr).match(/gh-0*(\d+)/i);
    if (m) return parseInt(m[1], 10);
    return null;
}

